def test_accepted_weight_subtracts_grade_deduction():
    assert accepted_weight_kg(order(weight="1000.000", deduction="12.345")) == Decimal("987.655")


def test_accepted_weight_null_or_zero_deduction_is_net_weight():
    assert accepted_weight_kg(order(weight="500.000", deduction=None)) == Decimal("500.000")
    assert accepted_weight_kg(order(weight="500.000", deduction="0")) == Decimal("500.000")


def test_accepted_weight_fully_rejected_is_zero():
    assert accepted_weight_kg(order(weight="500.000", deduction="500.000")) == Decimal("0.000")


def test_accepted_weight_zero_for_cancelled_order_with_deduction():
    assert accepted_weight_kg(order(status="cancelled", deduction="10")) == Decimal("0")


def test_order_value_uses_accepted_weight():
    # (1000 - 100) kg * 85 cents
    assert order_value_cents(order(weight="1000.000", price=85, deduction="100.000")) == 76_500


def test_reconcile_flags_billed_order_after_deduction_until_reversed():
    orders = [order(1, "ACM-1", deduction="100.000")]
    [m] = reconcile(orders, [entry(1, 85_000)])
    assert (m.expected_cents, m.booked_cents, m.diff_cents) == (76_500, 85_000, 8_500)
    # A reversing entry plus a corrected entry nets out.
    assert reconcile(orders, [entry(1, 85_000), entry(1, -85_000), entry(1, 76_500)]) == []


def test_order_value_is_exact_in_cents():

